import React, { useState } from "react";

const meses = [
  "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
  "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
];

// 💡 Cambiamos la prop "planilla" (singular) por "planillas" (arreglo de todas las planillas)
export default function ListadoPlanillas({ planillas = [], empleados = [], periodos = [], onVolver, onVerDetalle }) {
  // ===== HOOKS =====
  const [modalISR, setModalISR] = useState(false);
  const [modalCotizable, setModalCotizable] = useState(false);
  const [modalPlanillaUnica, setModalPlanillaUnica] = useState(false);
  
  // Estado para guardar qué periodo seleccionó el usuario en el filtro
  // Si hay periodos, toma el ID del primero por defecto; si no, vacío.
  const [periodoFiltro, setPeriodoFiltro] = useState(periodos[0]?.id || "");
  
  // Estado para guardar la planilla que se seleccionó para ver sus detalles en los modales
  const [planillaSeleccionada, setPlanillaSeleccionada] = useState(null);

  // ===== ⚡ LA MAGIA DEL FILTRO ⚡ =====
  // Filtramos el arreglo completo de planillas para que SÓLO se queden las que coinciden con el periodo seleccionado
  const planillasFiltradas = planillas.filter(pl => Number(pl.periodo_id) === Number(periodoFiltro));

  const perActual = periodos?.find(p => p.id === Number(periodoFiltro));

  // ===== DATOS PARA MODALES (Se activan al dar clic en los botones de la tabla) =====
  const desgloseCotizable = planillaSeleccionada ? {
    total: planillaSeleccionada.monto_cotizable || 0,
    sueldo_base: planillaSeleccionada.sueldo_base || 0,
    horas_extras_diurnas: planillaSeleccionada.monto_horas_extras_diurnas || 0,
    horas_extras_nocturnas: planillaSeleccionada.monto_horas_extras_nocturnas || 0,
    vacaciones: planillaSeleccionada.monto_vacaciones || 0,
    bono_extra: planillaSeleccionada.bono_extra || 0,
    aguinaldo_gravado: planillaSeleccionada.aguinaldo_gravado || 0,
    isss_empleado: planillaSeleccionada.monto_isss || 0, 
    afp_empleado: planillaSeleccionada.monto_afp || 0    
  } : null;

  const tramosISR = [
    { desde: "0.01", hasta: "550.00", cuota: "0.00", porcentaje: "0%" },
    { desde: "550.01", hasta: "895.24", cuota: "17.67", porcentaje: "10%" },
    { desde: "895.25", hasta: "2,038.10", cuota: "60.00", porcentaje: "20%" },
    { desde: "2,038.11", hasta: "∞", cuota: "288.57", porcentaje: "30%" }
  ];

  const abrirModalCotizable = (pl) => {
    setPlanillaSeleccionada(pl);
    setModalCotizable(true);
  };

  const abrirModalISR = (pl) => {
    setPlanillaSeleccionada(pl);
    setModalISR(true);
  };

  const abrirModalPlanillaUnica = (pl) => {
    setPlanillaSeleccionada(pl);
    setModalPlanillaUnica(true);
  };

  const cerrarModales = () => {
    setModalISR(false);
    setModalCotizable(false);
    setModalPlanillaUnica(false);
    setPlanillaSeleccionada(null);
  };

  const formatearFecha = (fechaStr) => {
    if (!fechaStr) return "Fecha no disponible";
    const fecha = new Date(fechaStr);
    return `${fecha.getDate()}/${meses[fecha.getMonth()]}/${fecha.getFullYear()}`;
  };

  const modalOverlayStyle = {
    position: "fixed", top: 0, left: 0, right: 0, bottom: 0,
    backgroundColor: "rgba(0,0,0,0.5)", display: "flex",
    alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "20px"
  };

  const modalContentStyle = {
    background: "white", borderRadius: "12px", padding: "25px",
    maxWidth: "600px", width: "100%", maxHeight: "80vh", overflowY: "auto",
    boxShadow: "0 10px 40px rgba(0,0,0,0.3)"
  };

  return (
    <>
      {/* ===== MODALES INFORMATIVOS ===== */}
      {modalISR && (
        <div style={modalOverlayStyle} onClick={cerrarModales}>
          <div style={modalContentStyle} onClick={(e) => e.stopPropagation()}>
            <h3 style={{ color: "#d71920", marginBottom: "15px" }}>📊 Tabla de Retención de ISR</h3>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "14px" }}>
              <thead>
                <tr style={{ backgroundColor: "#f2f2f2" }}>
                  <th style={{ padding: "8px", border: "1px solid #ddd" }}>Desde ($)</th>
                  <th style={{ padding: "8px", border: "1px solid #ddd" }}>Hasta ($)</th>
                  <th style={{ padding: "8px", border: "1px solid #ddd", textAlign: "right" }}>Cuota fija ($)</th>
                  <th style={{ padding: "8px", border: "1px solid #ddd", textAlign: "right" }}>%</th>
                </tr>
              </thead>
              <tbody>
                {tramosISR.map((tramo, idx) => (
                  <tr key={idx}>
                    <td style={{ padding: "8px", border: "1px solid #ddd" }}>{tramo.desde}</td>
                    <td style={{ padding: "8px", border: "1px solid #ddd" }}>{tramo.hasta}</td>
                    <td style={{ padding: "8px", border: "1px solid #ddd", textAlign: "right" }}>${tramo.cuota}</td>
                    <td style={{ padding: "8px", border: "1px solid #ddd", textAlign: "right" }}>{tramo.porcentaje}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div style={{ marginTop: "15px", textAlign: "right" }}>
              <button onClick={cerrarModales} style={{ background: "#6c757d", color: "white", border: "none", padding: "8px 20px", borderRadius: "8px", cursor: "pointer" }}>Cerrar</button>
            </div>
          </div>
        </div>
      )}

      {modalCotizable && desgloseCotizable && (
        <div style={modalOverlayStyle} onClick={cerrarModales}>
          <div style={modalContentStyle} onClick={(e) => e.stopPropagation()}>
            <h3 style={{ color: "#d71920", marginBottom: "15px" }}>📊 Desglose del Monto Cotizable</h3>
            
            <div style={{ background: "#f0f7ff", padding: "12px", borderRadius: "8px", borderLeft: "4px solid #007bff", marginBottom: "15px", fontSize: "13px" }}>
              <strong>💡 Importante (Base Imponible para ISR):</strong><br />
              La base imponible se obtiene restando el ISSS y la AFP al Monto Cotizable:
              <div style={{ marginTop: "5px", fontFamily: "monospace", fontWeight: "bold", color: "#0056b3" }}>
                ${desgloseCotizable.total.toFixed(2)} (Cotizable) 
                - ${desgloseCotizable.isss_empleado.toFixed(2)} (ISSS) 
                - ${desgloseCotizable.afp_empleado.toFixed(2)} (AFP) <br />
                = ${(desgloseCotizable.total - desgloseCotizable.isss_empleado - desgloseCotizable.afp_empleado).toFixed(2)} (Base Imponible)
              </div>
            </div>

            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "14px" }}>
              <tbody>
                <tr><td style={{ padding: "6px" }}>Sueldo base</td><td style={{ textAlign: "right" }}>${desgloseCotizable.sueldo_base.toFixed(2)}</td></tr>
                <tr><td style={{ padding: "6px" }}>Monto Vacaciones</td><td style={{ textAlign: "right" }}>${desgloseCotizable.vacaciones.toFixed(2)}</td></tr>
                <tr style={{ borderTop: "2px solid #d71920", fontWeight: "bold" }}>
                  <td style={{ padding: "8px" }}>TOTAL Monto Cotizable</td>
                  <td style={{ padding: "8px", textAlign: "right", color: "#d71920" }}>${desgloseCotizable.total.toFixed(2)}</td>
                </tr>
              </tbody>
            </table>
            <div style={{ marginTop: "15px", textAlign: "right" }}>
              <button onClick={cerrarModales} style={{ background: "#6c757d", color: "white", border: "none", padding: "8px 20px", borderRadius: "8px", cursor: "pointer" }}>Cerrar</button>
            </div>
          </div>
        </div>
      )}

      {modalPlanillaUnica && planillaSeleccionada && (
        <div style={modalOverlayStyle} onClick={cerrarModales}>
          <div style={modalContentStyle} onClick={(e) => e.stopPropagation()}>
            <h3 style={{ color: "#d71920", marginBottom: "15px" }}>📊 Monto a depositar planilla única</h3>
            <p style={{ background: "#f9f9f9", padding: "10px", borderRadius: "6px", borderLeft: "4px solid #d71920" }}>
              <strong>Monto calculado:</strong> ${planillaSeleccionada.monto_planilla_unica?.toFixed(2) || "0.00"}
            </p>
            <div style={{ marginTop: "15px", textAlign: "right" }}>
              <button onClick={cerrarModales} style={{ background: "#6c757d", color: "white", border: "none", padding: "8px 20px", borderRadius: "8px", cursor: "pointer" }}>Cerrar</button>
            </div>
          </div>
        </div>
      )}

      {/* ===== BANNER HERO ===== */}
      <section className="hero" style={{ height: "140px" }}>
        <div className="overlay">
          <h1 style={{ fontSize: "28px" }}>Planillas Registradas</h1>
        </div>
      </section>

      {/* ===== CONTENIDO PRINCIPAL ===== */}
      <div style={{ padding: "20px", background: "#f5f5f5", minHeight: "100vh" }}>
        <div style={{ maxWidth: "1200px", margin: "auto" }}>
          
          {/* ===== CONTROL DE FILTRO ===== */}
          <div style={{
            background: "white", borderRadius: "16px", padding: "20px 30px", marginBottom: "20px",
            boxShadow: "0 4px 12px rgba(0,0,0,0.06)", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "15px"
          }}>
            <div>
              <h2 style={{ color: "#d71920", margin: 0, fontSize: "22px" }}>TEXACO EL SALVADOR</h2>
              <p style={{ margin: "5px 0 0 0", color: "#666" }}>
                {perActual ? `Mostrando registros de: ${perActual.mes} / ${perActual.año}` : "Seleccione un período"}
              </p>
            </div>

            {/* Selector de periodo que filtra la tabla */}
            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <label style={{ fontWeight: "bold", color: "#555" }}>Filtrar por Período:</label>
              <select
                value={periodoFiltro}
                onChange={(e) => setPeriodoFiltro(e.target.value)}
                style={{ padding: "8px 12px", borderRadius: "8px", border: "1px solid #ccc", background: "white", cursor: "pointer" }}
              >
                <option value="">-- Seleccione Período --</option>
                {periodos?.map(p => (
                  <option key={p.id} value={p.id}>{p.mes} / {p.año}</option>
                ))}
              </select>
            </div>
          </div>

          {/* ===== TABLA CON REGISTROS FILTRADOS ===== */}
          <div style={{ background: "white", borderRadius: "16px", padding: "25px 30px", boxShadow: "0 4px 12px rgba(0,0,0,0.06)", overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "14px", textAlign: "left" }}>
              <thead>
                <tr style={{ backgroundColor: "#d71920", color: "white" }}>
                  <th style={{ padding: "12px" }}>Empleado</th>
                  <th style={{ padding: "12px" }}>Sueldo Base</th>
                  <th style={{ padding: "12px" }}>Cotizable ⓘ</th>
                  <th style={{ padding: "12px" }}>ISSS</th>
                  <th style={{ padding: "12px" }}>AFP</th>
                  <th style={{ padding: "12px" }}>ISR ⓘ</th>
                  <th style={{ padding: "12px" }}>Neto a Pagar</th>
                  <th style={{ padding: "12px" }}>Planilla Única ⓘ</th>
                </tr>
              </thead>
              <tbody>
                {planillasFiltradas.length > 0 ? (
                  planillasFiltradas.map((pl) => {
                    const emp = empleados?.find(e => e.id === pl.empleado_id);
                    return (
                      <tr key={pl.id} style={{ borderBottom: "1px solid #eee" }}>
                        <td style={{ padding: "12px" }}>
                          <strong>{emp ? emp.nombre : `ID: ${pl.empleado_id}`}</strong><br />
                          <small style={{ color: "#777" }}>{emp?.puesto || "N/A"}</small>
                        </td>
                        <td style={{ padding: "12px" }}>${pl.sueldo_base?.toFixed(2)}</td>
                        <td style={{ padding: "12px" }}>
                          ${pl.monto_cotizable?.toFixed(2)} 
                          <button onClick={() => abrirModalCotizable(pl)} style={{ border: "none", background: "none", color: "#007bff", cursor: "pointer", marginLeft: "4px" }}>ⓘ</button>
                        </td>
                        <td style={{ padding: "12px" }}>${pl.monto_isss?.toFixed(2)}</td>
                        <td style={{ padding: "12px" }}>${pl.monto_afp?.toFixed(2)}</td>
                        <td style={{ padding: "12px" }}>
                          ${pl.monto_isr?.toFixed(2)}
                          <button onClick={() => abrirModalISR(pl)} style={{ border: "none", background: "none", color: "#007bff", cursor: "pointer", marginLeft: "4px" }}>ⓘ</button>
                        </td>
                        <td style={{ padding: "12px", fontWeight: "bold", color: "#d71920" }}>${pl.monto_neto?.toFixed(2)}</td>
                        <td style={{ padding: "12px" }}>
                          ${pl.monto_planilla_unica?.toFixed(2)}
                          <button onClick={() => abrirModalPlanillaUnica(pl)} style={{ border: "none", background: "none", color: "#007bff", cursor: "pointer", marginLeft: "4px" }}>ⓘ</button>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan="8" style={{ padding: "30px", textAlign: "center", color: "#999", fontSize: "16px" }}>
                      ⚠️ No hay planillas registradas para el período seleccionado.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

        </div>
      </div>
    </>
  );
}
